using UnityEngine;

namespace GAMECON.Mission
{
    /// <summary>
    /// Procedural animation for a teammate whose skeleton was generated by the TeammateRigBuilder.
    /// Poses are described as the world direction each bone points in (character faces +Z, +X is her right side).
    ///
    /// stand = 0 .. 1 plays the whole "freed" sequence:
    ///   0.00  kneeling, head bowed, hands tied behind her back
    ///   0.28  hands free in front of her (rubbing her wrists), head lifting
    ///   0.58  lunge: one knee up, one knee down, leaning forward to push off
    ///   0.84  standing, still rubbing her wrists, looking up
    ///   1.00  standing relaxed
    /// Talking adds a nod and a hand gesture; Listening adds a slow nod. Breathing / sway are always on.
    /// </summary>
    public class CaptiveRig : MonoBehaviour
    {
        public enum B
        {
            Spine, Chest, Neck, Head, ShoulderP, ShoulderM, UpperArmP, UpperArmM, LowerArmP, LowerArmM, HandP, HandM,
            UpperLegP, UpperLegM, LowerLegP, LowerLegM, FootP, FootM
        }

        public Transform hips;
        public Transform[] bones = new Transform[18];       // indexed by B
        public Vector3[] bindDir = new Vector3[18];         // direction of each bone in the T-pose (root space)
        public Vector3 hipsBindLocalPos;
        public float height = 1.7f;

        [Range(0f, 1f)] public float stand;                // the whole sequence, 0 .. 1
        [Range(0f, 1f)] public float talk;                 // 0 silent .. 1 speaking
        [Range(0f, 1f)] public float listen;               // 0 .. 1 listening to someone
        public bool live = true;                           // animate in Play mode

        static readonly int[] parent =
        {
            -1, (int)B.Spine, (int)B.Chest, (int)B.Neck,                // spine, chest, neck, head
            (int)B.Chest, (int)B.Chest,                                  // shoulders
            (int)B.ShoulderP, (int)B.ShoulderM, (int)B.UpperArmP, (int)B.UpperArmM, (int)B.LowerArmP, (int)B.LowerArmM,
            -1, -1, (int)B.UpperLegP, (int)B.UpperLegM, (int)B.LowerLegP, (int)B.LowerLegM
        };

        void Start() { Apply(); }

        void Update()
        {
            if (live && Application.isPlaying) Apply();
        }

        public void SetState(float standing) { stand = Mathf.Clamp01(standing); Apply(); }
        public void SetTalking(float amount) { talk = Mathf.Clamp01(amount); }
        public void SetListening(float amount) { listen = Mathf.Clamp01(amount); }

        public Vector3 HeadWorld()
        {
            var h = bones[(int)B.Head];
            return h != null ? h.position + transform.up * (height * 0.045f) : transform.position + Vector3.up * height * 0.9f;
        }

        // ------------------------------------------------------------------------------------------------ poses
        // 0 = kneeling tied, 1 = kneeling hands free, 2 = lunge, 3 = standing (rubbing wrists), 4 = standing relaxed
        const int PK = 0, PK2 = 1, PL = 2, PW = 3, PS = 4;
        static readonly float[] hipsDrop = { 1f, 1f, 0.95f, 0f, 0f };           // fraction of the full kneeling drop
        static readonly float[] hipsFwd = { 0f, 0f, 0.05f, 0.01f, 0f };         // hips shift forward (x height)

        static Vector3 Dir(int pose, B b, float s)
        {
            bool plus = s > 0f;     // the right-hand side (+X) is the one that steps forward in the lunge
            switch (pose)
            {
                case PK:
                    switch (b)
                    {
                        case B.Spine:     return new Vector3(0f, 0.99f, 0.12f);
                        case B.Chest:     return new Vector3(0f, 0.97f, 0.22f);
                        case B.Neck:      return new Vector3(0f, 0.92f, 0.38f);
                        case B.Head:      return new Vector3(0f, 0.78f, 0.62f);
                        case B.ShoulderP: case B.ShoulderM: return new Vector3(s, 0.00f, -0.32f);
                        case B.UpperArmP: case B.UpperArmM: return new Vector3(s * 0.10f, -0.97f, -0.22f);
                        case B.LowerArmP: case B.LowerArmM: return new Vector3(-s * 0.60f, -0.28f, -0.75f);
                        case B.HandP:     case B.HandM:     return new Vector3(-s * 0.62f, -0.30f, -0.72f);
                    }
                    break;
                case PK2:
                    switch (b)
                    {
                        case B.Spine:     return new Vector3(0f, 0.995f, 0.05f);
                        case B.Chest:     return new Vector3(0f, 0.99f, 0.10f);
                        case B.Neck:      return new Vector3(0f, 0.97f, 0.20f);
                        case B.Head:      return new Vector3(0f, 0.93f, 0.36f);
                        case B.ShoulderP: case B.ShoulderM: return new Vector3(s, 0.02f, -0.04f);
                        case B.UpperArmP: case B.UpperArmM: return new Vector3(s * 0.20f, -0.96f, 0.16f);
                        case B.LowerArmP: case B.LowerArmM: return new Vector3(-s * 0.48f, -0.22f, 0.84f);
                        case B.HandP:     case B.HandM:     return new Vector3(-s * 0.55f, -0.12f, 0.83f);
                    }
                    break;
                case PL:
                    switch (b)
                    {
                        case B.Spine:     return new Vector3(0f, 0.95f, 0.30f);
                        case B.Chest:     return new Vector3(0f, 0.95f, 0.30f);
                        case B.Neck:      return new Vector3(0f, 0.97f, 0.24f);
                        case B.Head:      return new Vector3(0f, 0.98f, 0.20f);
                        case B.ShoulderP: case B.ShoulderM: return new Vector3(s, 0.02f, 0.02f);
                        case B.UpperArmP: case B.UpperArmM: return new Vector3(s * 0.22f, -0.95f, 0.22f);
                        case B.LowerArmP: case B.LowerArmM: return new Vector3(-s * 0.45f, -0.18f, 0.87f);
                        case B.HandP:     case B.HandM:     return new Vector3(-s * 0.52f, -0.10f, 0.85f);
                    }
                    break;
                case PW:
                    switch (b)
                    {
                        case B.Spine:     return new Vector3(0f, 1f, 0.04f);
                        case B.Chest:     return new Vector3(0f, 1f, 0.04f);
                        case B.Neck:      return new Vector3(0f, 1f, 0.07f);
                        case B.Head:      return new Vector3(0f, 0.99f, 0.14f);
                        case B.ShoulderP: case B.ShoulderM: return new Vector3(s, 0.02f, 0.02f);
                        case B.UpperArmP: case B.UpperArmM: return new Vector3(s * 0.14f, -0.98f, 0.14f);
                        case B.LowerArmP: case B.LowerArmM: return new Vector3(-s * 0.46f, -0.34f, 0.82f);
                        case B.HandP:     case B.HandM:     return new Vector3(-s * 0.50f, -0.30f, 0.81f);
                    }
                    break;
                default: // PS
                    switch (b)
                    {
                        case B.Spine:     return new Vector3(0f, 1f, 0f);
                        case B.Chest:     return new Vector3(0f, 1f, 0.01f);
                        case B.Neck:      return new Vector3(0f, 1f, 0.05f);
                        case B.Head:      return new Vector3(0f, 0.99f, 0.10f);
                        case B.ShoulderP: case B.ShoulderM: return new Vector3(s, 0.02f, 0f);
                        case B.UpperArmP: case B.UpperArmM: return new Vector3(s * 0.14f, -0.99f, 0.02f);
                        case B.LowerArmP: case B.LowerArmM: return new Vector3(s * 0.05f, -0.96f, 0.24f);
                        case B.HandP:     case B.HandM:     return new Vector3(s * 0.04f, -0.97f, 0.24f);
                    }
                    break;
            }

            // legs
            if (pose == PK || pose == PK2)
                switch (b)
                {
                    case B.UpperLegP: case B.UpperLegM: return new Vector3(s * 0.05f, -1f, 0f);
                    case B.LowerLegP: case B.LowerLegM: return new Vector3(s * 0.06f, -0.04f, -1f);
                    case B.FootP:     case B.FootM:     return new Vector3(0f, -0.62f, -0.78f);
                }
            else if (pose == PL)
            {
                if (plus)
                    switch (b)
                    {
                        case B.UpperLegP: return new Vector3(0.04f, -0.42f, 0.91f);       // front leg: thigh forward, shin down, foot flat
                        case B.LowerLegP: return new Vector3(0.02f, -0.86f, -0.50f);
                        case B.FootP:     return new Vector3(0f, -0.06f, 1f);
                    }
                else
                    switch (b)
                    {
                        case B.UpperLegM: return new Vector3(-0.05f, -1f, 0f);            // rear leg: still kneeling
                        case B.LowerLegM: return new Vector3(-0.06f, -0.04f, -1f);
                        case B.FootM:     return new Vector3(0f, -0.62f, -0.78f);
                    }
            }
            else
                switch (b)
                {
                    case B.UpperLegP: case B.UpperLegM: return new Vector3(s * 0.03f, -1f, 0f);
                    case B.LowerLegP: case B.LowerLegM: return new Vector3(0f, -1f, 0f);
                    case B.FootP:     case B.FootM:     return new Vector3(0f, -0.08f, 1f);
                }
            return Vector3.up;
        }

        static bool IsPlus(B b)
        {
            return b == B.ShoulderP || b == B.UpperArmP || b == B.LowerArmP || b == B.HandP || b == B.UpperLegP || b == B.LowerLegP || b == B.FootP;
        }

        static float Ease(float k) { k = Mathf.Clamp01(k); return k * k * (3f - 2f * k); }

        /// <summary>Writes the current pose into the bone transforms.</summary>
        public void Apply()
        {
            if (hips == null || bones == null || bones.Length < 18) return;
            float t = Application.isPlaying ? Time.unscaledTime : 0f;

            // which two key poses are we between?
            int a, c; float f;
            float s = stand;
            if (s < 0.28f)      { a = PK;  c = PK2; f = s / 0.28f; }
            else if (s < 0.58f) { a = PK2; c = PL;  f = (s - 0.28f) / 0.30f; }
            else if (s < 0.84f) { a = PL;  c = PW;  f = (s - 0.58f) / 0.26f; }
            else                { a = PW;  c = PS;  f = (s - 0.84f) / 0.16f; }
            f = Ease(f);

            float sway = Mathf.Clamp01(1f - s * 3.5f);                // tired sway only while still kneeling
            float up = Mathf.Clamp01((s - 0.84f) / 0.16f);             // fully standing

            // hips: lowered while kneeling, rising during the lunge, with a small weight shift when standing
            float drop = Mathf.Lerp(hipsDrop[a], hipsDrop[c], f);
            float fwd = Mathf.Lerp(hipsFwd[a], hipsFwd[c], f);
            Vector3 hp = hipsBindLocalPos + Vector3.down * (height * 0.245f * drop) + Vector3.forward * (height * fwd);
            hp.x += height * 0.012f * Mathf.Sin(t * 0.7f) * up;
            hips.localPosition = hp;

            var rotRoot = new Quaternion[18];
            for (int i = 0; i < 18; i++)
            {
                var b = (B)i;
                var tr = bones[i];
                if (tr == null) continue;
                float sd = IsPlus(b) ? 1f : -1f;
                Vector3 d = Vector3.Slerp(Dir(a, b, sd).normalized, Dir(c, b, sd).normalized, f);

                // alive: breathing + sway while kneeling; idle motion when standing
                float breath = Mathf.Sin(t * 1.9f);
                if (b == B.Chest) d.y += 0.012f * breath;
                if (b == B.Spine) d.z += 0.015f * breath * sway;
                if (b == B.Head)
                {
                    d.z += 0.03f * Mathf.Sin(t * 0.9f) * sway;                                // tired head sway
                    d.x += 0.025f * Mathf.Sin(t * 0.55f) * up;                                // looks around slightly
                    d.z += talk * 0.05f * Mathf.Sin(t * 3.1f);                                // nod while speaking
                    d.x += talk * 0.06f * Mathf.Sin(t * 1.7f + 1f);
                    d.z += listen * 0.045f * Mathf.Max(0f, Mathf.Sin(t * 1.3f));              // slow nods while listening
                }
                if (up > 0f && (b == B.UpperArmP || b == B.UpperArmM)) d.z += 0.03f * Mathf.Sin(t * 1.1f + sd) * up;   // arms never perfectly still

                // speaking: right hand gestures
                if ((b == B.LowerArmP || b == B.HandP) && talk > 0f)
                {
                    float g = talk * (0.55f + 0.45f * Mathf.Sin(t * 2.3f)) * Mathf.Clamp01((s - 0.7f) / 0.3f);
                    d = Vector3.Slerp(d, new Vector3(0.22f, -0.30f, 0.92f).normalized, g * 0.75f);
                }

                Quaternion r = Quaternion.FromToRotation(bindDir[i].normalized, d.normalized);
                int p = parent[i];
                Quaternion pr = p >= 0 ? rotRoot[p] : Quaternion.identity;
                tr.localRotation = Quaternion.Inverse(pr) * r;
                rotRoot[i] = r;
            }
        }
    }
}
